        # Check if the resulting number is a perfect square
        k = int(loc) ** 0.5
        if int(k) != k:
            continue

        # Update the maximum length of the valid square number found
        if len(loc) > m:
            m = len(loc)

    # Calculate the minimum number of operations required
    return e - m if m != 0 else -1
